import React, { useState } from "react";
import axios from "axios";
import { getFirestore, collection, addDoc } from "firebase/firestore";
import { app } from "../../../firebaseConfig"; // Firebase setup

const firestore = getFirestore(app);

const ImageUploader = () => {
  const [slider, setSlider] = useState(null);
  const [bigPhoto, setBigPhoto] = useState(null);
  const [allPhotos, setAllPhotos] = useState([]);
  const [uploadedData, setUploadedData] = useState<({
    allPhoto: [],
  });

  const handleUpload = async () => {
    if (!slider || !bigPhoto || allPhotos.length === 0) {
      alert("Please select a Slider photo, a Big photo, and at least 1 additional image.");
      return;
    }

    const formData = new FormData();
    formData.append("slider", slider);
    formData.append("bigPhoto", bigPhoto);
    allPhotos.forEach((img) => formData.append("allPhotos", img));

    try {
      const { data } = await axios.post("http://localhost:5000/upload", formData);

      const structuredData = {
        slider: data.sliderUrl,
        bigPhoto: data.bigPhotoUrl,
        allPhoto: data.allPhotoUrls,
      };

      setUploadedData(structuredData);

      // Store in Firebase Firestore
      await addDoc(collection(firestore, "uploads-images"), {
        uploadedAt: new Date(),
        ...structuredData,
      });

      console.log("Images uploaded:", structuredData);
    } catch (error) {
      console.error("Upload failed", error);
    }
  };

  return (
    <div>
      <h3>Upload Slider Photo</h3>
      <input type="file" onChange={(e) => setSlider(e.target.files?.[0] || null)} />

      <h3>Upload Big Photo</h3>
      <input type="file" onChange={(e) => setBigPhoto(e.target.files?.[0] || null)} />

      <h3>Upload All Photos</h3>
      <input type="file" multiple onChange={(e) => setAllPhotos(Array.from(e.target.files || []))} />

      <button onClick={handleUpload}>Upload</button>

      {uploadedData.slider && <img src={uploadedData.slider} alt="Slider" width="200px" />}
      {uploadedData.bigPhoto && <img src={uploadedData.bigPhoto} alt="Big Photo" width="200px" />}
      {uploadedData.allPhoto.length > 0 && (
        <div>
          <h3>All Photos</h3>
          {uploadedData.allPhoto.map((url, index) => (
            <img key={index} src={url} alt={`AllPhoto-${index}`} width="150px" />
          ))}
        </div>
      )}
    </div>
  );
};

export default ImageUploader;
